/* Coffeebreak Studio Espresso - editor, mastering, tools, karaoke, browser, export, pages, start-up */
/* ---------- audio editor ---------- */
const ED={sel:null,clip:null,drag:null};
function edTarget(){ const t=selTrack(),c=selClip(); return t&&t.kind==='audio'&&c?{t,c,b:BUFS[c.takes[c.take]]}:null; }
function edView(){ const s=edTarget(),cv=$('#edWave'); $('#edInfo').textContent=s?`${s.c.name}, take ${s.c.take+1}: ${s.b.duration.toFixed(2)} s, ${s.b.sampleRate} Hz, peak ${(20*Math.log10(peakOf(s.b)+1e-9)).toFixed(1)} dB. Drag to select. No selection means the whole clip.`:'Select an audio clip in Arrange.'; drawWaveX(cv,s&&s.b,ED.sel); }
function drawWaveX(cv,b,sel){ const W=cv.width=cv.clientWidth||800,H=cv.height,g=cv.getContext('2d'); g.fillStyle='#2e1422'; g.fillRect(0,0,W,H); if(!b)return; const chs=b.numberOfChannels,hh=H/chs;
 if(sel&&sel[1]>sel[0]){g.fillStyle='#ffd6e855';g.fillRect(sel[0]/b.length*W,0,(sel[1]-sel[0])/b.length*W,H)}
 for(let c=0;c<chs;c++){ const d=b.getChannelData(c),st=Math.max(1,Math.floor(d.length/W)); g.fillStyle='#e75b9a'; for(let x=0;x<W;x++){ let mn=1,mx=-1; for(let i=x*st;i<(x+1)*st&&i<d.length;i+=2){const v=d[i];if(v<mn)mn=v;if(v>mx)mx=v} if(mx<mn)continue; g.fillStyle=mx>=0.999||mn<=-0.999?'#f33':'#e75b9a'; g.fillRect(x,c*hh+(1-mx)*hh/2,1,Math.max(1,(mx-mn)*hh/2)); } } }
let EDCLIP=null;
async function edOp(op){ const s=edTarget(); if(!s)return toast('Select an audio clip first'); const b=s.b,sr=b.sampleRate; let[a,e]=ED.sel&&ED.sel[1]-ED.sel[0]>32?ED.sel:[0,b.length]; const whole=a===0&&e===b.length; let out=null; toast('Working...',60000);
 const region=async fn=>{ const part=sliceBuf(b,a,e),r=await fn(part),o=newBuf(b.numberOfChannels,b.length-(e-a)+r.length,sr); for(let c=0;c<o.numberOfChannels;c++){const d=o.getChannelData(c),src=b.getChannelData(c),rr=r.getChannelData(Math.min(c,r.numberOfChannels-1));d.set(src.subarray(0,a),0);d.set(rr,a);d.set(src.subarray(e),a+r.length)} return o; };
 try{ switch(op){
  case'cut':EDCLIP=sliceBuf(b,a,e); out=concatBufs([sliceBuf(b,0,a),sliceBuf(b,e,b.length)],sr,b.numberOfChannels); break;
  case'copy':EDCLIP=sliceBuf(b,a,e); toast('Copied '+((e-a)/sr).toFixed(2)+' s'); return;
  case'paste':if(!EDCLIP)return toast('Copy something first'); out=concatBufs([sliceBuf(b,0,a),toStereoN(EDCLIP,b.numberOfChannels),sliceBuf(b,a,b.length)],sr,b.numberOfChannels); break;
  case'del':out=concatBufs([sliceBuf(b,0,a),sliceBuf(b,e,b.length)],sr,b.numberOfChannels); break;
  case'trim':out=sliceBuf(b,a,e); break;
  case'silence':out=await region(p=>gainBuf(cloneBuf(p),0)); break;
  case'fin':out=await region(p=>fadeBuf(p,0,p.length,'in')); break;
  case'fout':out=await region(p=>fadeBuf(p,0,p.length,'out')); break;
  case'rev':out=await region(p=>reverseBuf(p)); break;
  case'norm':out=await region(p=>normaliseBuf(p,-1)); break;
  case'g+':out=await region(p=>gainBuf(cloneBuf(p),dbToG(3))); break;
  case'g-':out=await region(p=>gainBuf(cloneBuf(p),dbToG(-3))); break;
  case'stretch':{ const r=+$('#edStr').value; if(!(r>0.25&&r<4))return toast('Use a stretch between 0.25 and 4'); out=await region(p=>wsola(p,r)); break; }
  case'pitch':{ const st=+$('#edPit').value; out=await region(p=>pitchShiftBuf(p,st)); break; }
  case'nr':{ const prof=ED.sel&&!whole?sliceBuf(b,a,e):null; out=await spectralNR(b,prof); a=0;e=b.length; break; }
  case'deess':out=await region(p=>deEss(p)); break;
  case'gate':out=await region(p=>gate(cloneBuf(p))); break;
  case'click':{ out=cloneBuf(b); let n=0; for(let c=0;c<out.numberOfChannels;c++){const d=out.getChannelData(c).subarray(a,e);n+=declick(d)} toast('Repaired '+n+' clicks'); break; }
  case'derev':out=await region(p=>dereverb(p,0.6)); break;
  case'mono':out=await region(p=>{const m=monoOf(p),o=newBuf(p.numberOfChannels,p.length,sr);for(let c=0;c<o.numberOfChannels;c++)o.copyToChannel(m,c);return o}); break;
  case'key':toast('Detected key: '+detectKey(sliceBuf(b,a,e)),5000); return;
  case'bpm':toast('Estimated tempo: '+estimateBPM(sliceBuf(b,a,e))+' BPM',5000); return;
 } }catch(err){ return toast('That edit failed: '+err.message); }
 snap(); const id=addBuf(out); s.c.takes[s.c.take]=id; const newLen=s2b(b2s(s.c.start)+out.duration-(s.c.offset||0))-s.c.start; if(['cut','paste','del','trim','stretch'].includes(op)||Math.abs(out.length-b.length)>sr*0.01)s.c.len=Math.max(0.1,newLen);
 ED.sel=['cut','del','trim'].includes(op)?null:ED.sel; toast('Done'); edView(); drawTL(); }
function toStereoN(b,n){ if(b.numberOfChannels===n)return b; const o=newBuf(n,b.length,b.sampleRate); for(let c=0;c<n;c++)o.copyToChannel(b.getChannelData(Math.min(c,b.numberOfChannels-1)),c); return o; }
function estimateBPM(b){ const sr=b.sampleRate,d=monoOf(b),hop=512,env=[]; let prev=0; for(let i=0;i+hop<d.length;i+=hop){let s=0;for(let j=i;j<i+hop;j++)s+=d[j]*d[j];const e=Math.sqrt(s/hop);env.push(Math.max(0,e-prev));prev=e}
 const fps=sr/hop; let best=120,bv=-1; for(let bpm=60;bpm<=180;bpm+=0.5){const lag=fps*60/bpm;let s=0;for(let i=0;i+lag<env.length;i++)s+=env[i]*env[Math.round(i+lag)];if(s>bv){bv=s;best=bpm}} return best; }
function initEditor(){ const cv=$('#edWave'); cv.onpointerdown=e=>{ const s=edTarget(); if(!s)return; cv.setPointerCapture(e.pointerId); const r=cv.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*s.b.length; ED.drag=x; ED.sel=[x,x]; edView(); };
 cv.onpointermove=e=>{ if(ED.drag==null)return; const s=edTarget(),r=cv.getBoundingClientRect(),x=Math.max(0,Math.min(s.b.length,(e.clientX-r.left)/r.width*s.b.length)); ED.sel=[Math.min(ED.drag,x)|0,Math.max(ED.drag,x)|0]; drawWaveX(cv,s.b,ED.sel); };
 cv.onpointerup=()=>{ ED.drag=null; }; $$('#t-editor [data-op]').forEach(b=>b.onclick=()=>edOp(b.dataset.op));
 $('#edPlay').onclick=()=>{ const s=edTarget(); if(!s)return; const c=AC(); if(ED.src){try{ED.src.stop()}catch(e){}ED.src=null;return} const src=c.createBufferSource(); src.buffer=s.b; src.connect(c.destination); const[a,e]=ED.sel&&ED.sel[1]-ED.sel[0]>100?ED.sel:[0,s.b.length]; src.start(0,a/s.b.sampleRate,(e-a)/s.b.sampleRate); ED.src=src; src.onended=()=>ED.src=null; };
 $('#edAll').onclick=()=>{ ED.sel=null; edView(); }; }
/* ---------- mastering ---------- */
const MPRE={'Streaming -14 LUFS':{l:0.5,m:0,h:1,c:0.5,w:1.05,t:-14},'Radio loud':{l:1.5,m:0.5,h:2,c:0.9,w:1.1,t:-9},Warm:{l:2.5,m:-0.5,h:-1.5,c:0.5,w:1,t:-14},Bright:{l:-0.5,m:0.5,h:3,c:0.55,w:1.15,t:-14},Country:{l:1,m:1.5,h:1.5,c:0.6,w:1.1,t:-13},Pop:{l:2,m:-0.5,h:2.5,c:0.75,w:1.2,t:-11},Gentle:{l:0,m:0,h:0.5,c:0.25,w:1,t:-16},'Club':{l:3,m:0,h:1.5,c:0.85,w:1.15,t:-8},'Podcast voice':{l:-1,m:1.5,h:1,c:0.7,w:0.8,t:-16},'Lo-fi chill':{l:1.5,m:-1,h:-3,c:0.5,w:1,t:-14}};
function masterView(){ const box=$('#mPar'); box.innerHTML=''; const p=P.master.p; [['l','Low dB',-8,8,0.5],['m','Mid dB',-8,8,0.5],['h','High dB',-8,8,0.5],['c','Compression',0,1,0.05],['w','Stereo width',0,2,0.05],['t','Target LUFS',-24,-6,0.5]].forEach(([k,n,a,b,s])=>box.appendChild(slider(n,p[k],a,b,s,(v,fin)=>{if(fin)snap();p[k]=v;if(fin&&P.master.live)rebuildIfPlaying()})));
 $('#mPre').innerHTML=Object.keys(MPRE).map(k=>`<button>${k}</button>`).join(''); $$('#mPre button').forEach(b=>b.onclick=()=>{snap();P.master.p=Object.assign({},MPRE[b.textContent]);masterView();if(P.master.live)rebuildIfPlaying();toast(b.textContent)});
 $('#mOn').checked=P.master.on; $('#mLive').checked=P.master.live; }
function initMaster(){ $('#mOn').onchange=()=>{snap();P.master.on=$('#mOn').checked}; $('#mLive').onchange=()=>{snap();P.master.live=$('#mLive').checked;rebuildIfPlaying()};
 $('#mMeasure').onclick=async()=>{ toast('Measuring the mix...',60000); try{ const b=await renderSong({}); const r=await renderMaster(b,P.master.p); P.master.makeup=r.gain; $('#mRes').textContent=`Mix ${(await measureLUFS(b)).toFixed(1)} LUFS, mastered ${r.lufs.toFixed(1)} LUFS (approx). Live preview now uses this gain.`; toast('Measured'); }catch(e){toast(e.message)} };
 $('#refFile').onchange=async e=>{ const f=e.target.files[0]; if(!f)return; try{ refAB.buf=await decodeFile(f); const l=await measureLUFS(refAB.buf); refAB.lvl=dbToG(Math.max(-12,Math.min(0,P.master.p.t-l))); $('#refInfo').textContent=f.name+' loaded, '+l.toFixed(1)+' LUFS. Level matched to your target for a fair comparison.'; }catch(er){toast('Cannot open that file')} };
 $('#refAB').onclick=refToggle; $('#lufsReset').onclick=()=>{LH.length=0;LINT={sum:0,n:0}}; }
/* ---------- tools ---------- */
let TUNER=null;
async function tunerToggle(){ if(TUNER){ clearInterval(TUNER.i); TUNER.src.disconnect(); TUNER=null; $('#tunBtn').textContent='Start tuner'; $('#tunOut').textContent='--'; return; }
 try{ const c=AC(),st=await getStream(''),src=c.createMediaStreamSource(st),an=c.createAnalyser(); an.fftSize=4096; src.connect(an); const buf=new Float32Array(4096); const ref=+$('#tunRef').value||440;
  TUNER={src,i:setInterval(()=>{ an.getFloatTimeDomainData(buf); const f=detectPitch(buf,c.sampleRate); if(!f)return; const m=69+12*Math.log2(f/ref),n=Math.round(m),cents=Math.round((m-n)*100); $('#tunOut').textContent=`${NOTE_NAMES[(n%12+12)%12]}${Math.floor(n/12)-1}  ${cents>0?'+':''}${cents} cents  (${f.toFixed(1)} Hz)`; $('#tunOut').style.color=Math.abs(cents)<6?'#2a9d55':'#e75b9a'; },80)}; $('#tunBtn').textContent='Stop tuner'; }
 catch(e){ toast('Microphone not available: '+e.message); } }
let REFTONE=null;
function refTone(){ const c=AC(); if(REFTONE){REFTONE.stop();REFTONE=null;return} const o=c.createOscillator(),g=c.createGain(); o.frequency.value=+$('#tunRef').value||440; g.gain.value=0.15; o.connect(g); g.connect(c.destination); o.start(); REFTONE=o; }
const TAPS=[];
function tap(){ const n=performance.now(); if(TAPS.length&&n-TAPS[TAPS.length-1]>2000)TAPS.length=0; TAPS.push(n); if(TAPS.length>8)TAPS.shift(); if(TAPS.length>1){ const bpm=60000/((TAPS[TAPS.length-1]-TAPS[0])/(TAPS.length-1)); $('#tapOut').textContent=bpm.toFixed(1)+' BPM'; $('#tapOut').dataset.bpm=Math.round(bpm); } }
function chordView(){ const k=+$('#chKey').value,sc=$('#chSc').value,S=SCALES[sc]; $('#chNotes').textContent='Notes: '+S.map(i=>NOTE_NAMES[(k+i)%12]).join(' ');
 if(S.length!==7){ $('#chChords').innerHTML='<span class="hint">Chords are shown for 7-note scales.</span>'; return; } const roman=['I','II','III','IV','V','VI','VII'];
 $('#chChords').innerHTML=S.map((_,d)=>{ const ns=[0,2,4].map(j=>S[(d+j)%7]+12*Math.floor((d+j)/7)),i3=(ns[1]-ns[0]+12)%12,i5=(ns[2]-ns[0]+12)%12,q=i3===4&&i5===7?'':i3===3&&i5===7?'m':i3===3&&i5===6?'dim':'aug'; const nm=NOTE_NAMES[(k+S[d])%12]+q,ro=q==='m'||q==='dim'?roman[d].toLowerCase():roman[d];
  return `<button data-n="${ns.map(n=>60+k+n).join(',')}">${ro}: ${nm}</button>`; }).join(''); $$('#chChords button').forEach(b=>b.onclick=()=>{ const c=AC(),t=liveTrack(); const ins=t&&t.inst.type!=='drums'?t.inst:instNew('fm'); b.dataset.n.split(',').forEach(p=>playNote(c,t?liveDest(t):c.destination,ins,+p,c.currentTime,1,0.6)); }); }
function initTools(){ $('#tunBtn').onclick=tunerToggle; $('#tunTone').onclick=refTone; $('#tapBtn').onclick=tap; $('#tapSet').onclick=()=>{const b=+$('#tapOut').dataset.bpm;if(b){snap();P.bpm=b;refreshAll();toast('Project tempo set to '+b)}};
 $('#chKey').innerHTML=NOTE_NAMES.map((n,i)=>`<option value="${i}">${n}</option>`).join(''); $('#chSc').innerHTML=Object.keys(SCALES).map(s=>`<option>${s}</option>`).join(''); $('#chKey').onchange=$('#chSc').onchange=chordView; chordView();
 $('#keyBtn').onclick=async()=>{ const s=edTarget(); toast('Analysing...'); try{ const b=s?s.b:await renderSong({}); $('#keyOut').textContent=(s?'Selected clip':'Whole mix')+': '+detectKey(b)+', about '+estimateBPM(b)+' BPM'; }catch(e){toast(e.message)} };
 $('#lyr').value=P.lyrics||''; $('#lyr').oninput=()=>{P.lyrics=$('#lyr').value}; $('#lyrSave').onclick=()=>dl(new Blob([$('#lyr').value],{type:'text/plain'}),(P.name||'lyrics')+'.txt');
 $('#lyrLoad').onchange=async e=>{const f=e.target.files[0];if(f){$('#lyr').value=P.lyrics=await f.text()}};
 $('#lyrRhyme').onclick=()=>{ const w=($('#lyrWord').value||'').toLowerCase().trim(); if(!w)return; const end=w.slice(-2); const words=($('#lyr').value+' '+RHYME_BANK).toLowerCase().match(/[a-z']+/g)||[]; const r=[...new Set(words.filter(x=>x!==w&&x.endsWith(end)))].slice(0,30); $('#lyrR').textContent=r.length?r.join(', '):'No matches in the word bank'; };
 $('#tmAdd').onclick=()=>{ const bar=+$('#tmBar').value,bpm=+$('#tmBpm').value; if(!(bar>1&&bpm>=30))return toast('Pick a bar after bar 1 and a tempo'); snap(); P.tempo=(P.tempo||[]).filter(x=>x[0]!==(bar-1)*P.sig); P.tempo.push([(bar-1)*P.sig,bpm]); tmView(); drawTL(); };
 $('#mkAdd').onclick=()=>{ const n=prompt('Marker name','Chorus'); if(!n)return; snap(); P.markers.push({b:T.pos,name:n}); P.markers.sort((a,b)=>a.b-b.b); tmView(); drawTL(); }; tmView(); }
function tmView(){ $('#tmList').innerHTML=(P.tempo||[]).map((x,i)=>`<button data-i="${i}">Bar ${x[0]/P.sig+1}: ${x[1]} BPM (remove)</button>`).join('')||'<span class="hint">Constant tempo</span>';
 $$('#tmList button').forEach(b=>b.onclick=()=>{snap();P.tempo.splice(+b.dataset.i,1);tmView();drawTL()});
 $('#mkList').innerHTML=P.markers.map((m,i)=>`<button data-i="${i}">${esc(m.name)} (bar ${(m.b/P.sig+1).toFixed(1)})</button><button class="sm" data-d="${i}">x</button>`).join('')||'<span class="hint">No markers yet</span>';
 $$('#mkList button[data-i]').forEach(b=>b.onclick=()=>seek(P.markers[+b.dataset.i].b)); $$('#mkList button[data-d]').forEach(b=>b.onclick=()=>{snap();P.markers.splice(+b.dataset.d,1);tmView();drawTL()}); }
const RHYME_BANK='love above dove of heart start apart part art night light bright tight fight right sight day way stay play say away okay mud flood blood bud sky high fly try why cry by fire desire higher wire home alone stone phone gone song long strong wrong along belong town down around sound ground found sweet street beat heat feet meet cream dream team seem gleam rain again pain chain lane train smile while mile style';
/* ---------- karaoke (vocal reducer, lyrics, mic chain, record performance) ---------- */
const K={songs:[],cur:-1,src:null,t0:0,lines:[],timed:false,mic:null,rec:null};
function kParse(txt){ const out=[]; let timed=false; txt.split(/\r?\n/).forEach(l=>{ const m=/^\[(\d+):(\d+(?:\.\d+)?)\](.*)$/.exec(l.trim()); if(m){timed=true;out.push({t:+m[1]*60+ +m[2],s:m[3].trim()})} else if(l.trim())out.push({t:null,s:l.trim()}); }); K.timed=timed; return out; }
function kGraph(c,dest){ const s=K.songs[K.cur]; const src=c.createBufferSource(); src.buffer=s.buf; const out=c.createGain(); out.gain.value=+$('#kVol').value;
 if($('#kRed').checked&&s.buf.numberOfChannels>1){ const sp=c.createChannelSplitter(2),inv=c.createGain(); inv.gain.value=-1; const side=c.createGain(); src.connect(sp); sp.connect(side,0); sp.connect(inv,1); inv.connect(side); const hp=c.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=200; side.connect(hp); hp.connect(out);
  const lp=c.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=160; src.connect(lp); lp.connect(out); } else src.connect(out); out.connect(dest); return src; }
function kPlay(){ const c=AC(); if(K.src){ kStop(); return; } if(K.cur<0)return toast('Upload a song first'); K.src=kGraph(c,c.destination); K.t0=c.currentTime+0.05; K.src.start(K.t0); K.src.onended=()=>{ if(K.src)kStop(); }; $('#kPlay').textContent='Stop'; kTick(); }
function kStop(){ if(K.src){try{K.src.stop()}catch(e){}K.src=null} $('#kPlay').textContent='Play'; if(K.rec)kRecStop(); }
function kTick(){ if(!K.src)return; const t=ctx.currentTime-K.t0,s=K.songs[K.cur],L=K.lines; let i=-1;
 if(L.length){ if(K.timed){ for(let k=0;k<L.length;k++)if(L[k].t!=null&&L[k].t<=t)i=k; } else i=Math.min(L.length-1,Math.floor(t/s.buf.duration*L.length)); }
 if(K.manual!=null)i=K.manual; $('#kLyr').innerHTML=L.length?L.map((l,k)=>Math.abs(k-i)<=2?`<div class="${k===i?'cur':''}">${esc(l.s)}</div>`:'').join(''):'Add lyrics below to see them here';
 $('#kTime').textContent=t.toFixed(1)+' / '+s.buf.duration.toFixed(1)+' s'; requestAnimationFrame(kTick); }
async function kMic(){ const c=AC(); if(K.mic){ K.mic.src.disconnect(); K.mic.out.disconnect(); K.mic=null; $('#kMic').textContent='Turn mic on'; return; } await ensureWorklet(c); WL_OK.set(c,true);
 try{ const st=await getStream(''),src=c.createMediaStreamSource(st); const boost=c.createGain(); boost.gain.value=+$('#kBoost').value; let last=boost; src.connect(boost);
  if($('#kGate').checked){ const g=wnode(c,'cbx-gate',{threshold:+$('#kGateL').value}); if(g){last.connect(g);last=g} }
  const semi=+$('#kShift').value; if(semi){ const sh=wnode(c,'cbx-shift',{semi,mix:1,dry:0}); if(sh){last.connect(sh);last=sh} }
  const rv=FXDEF.reverb.b(c,{size:2,decay:3,predelay:0.02,mix:+$('#kRev').value}); last.connect(rv.i); last=rv.o; const out=c.createGain(); last.connect(out); const mon=c.createGain(); mon.gain.value=$('#kMon').checked?1:0; out.connect(mon); mon.connect(c.destination);
  K.mic={src,out,mon}; $('#kMic').textContent='Turn mic off'; toast($('#kMon').checked?'Mic on, you can hear yourself (use headphones)':'Mic on'); }catch(e){ toast('Microphone not available: '+e.message); } }
async function kRec(){ if(K.rec)return kRecStop(); if(!K.mic)await kMic(); if(!K.mic)return; const c=ctx; await ensureWorklet(c); const node=new AudioWorkletNode(c,'cbx-rec'),mix=c.createGain(); K.mic.out.connect(mix); const ch=[[],[]];
 node.port.onmessage=e=>{ch[0].push(e.data[0]);ch[1].push(e.data[1])}; if(K.src)kStop(); K.src=kGraph(c,mix); K.src.onended=()=>{if(K.rec)kRecStop()}; const z=c.createGain(); z.gain.value=0; mix.connect(node); node.connect(z); z.connect(c.destination); K.t0=c.currentTime+0.05; K.src.start(K.t0); K.rec={node,mix,ch}; $('#kRec').classList.add('on'); $('#kPlay').textContent='Stop'; kTick(); }
async function kRecStop(){ const R=K.rec; K.rec=null; R.node.port.postMessage('flush'); await new Promise(r=>setTimeout(r,200)); if(K.src){try{K.src.stop()}catch(e){}K.src=null} $('#kPlay').textContent='Play'; $('#kRec').classList.remove('on'); R.mix.disconnect(); R.node.disconnect();
 const n=R.ch[0].reduce((a,x)=>a+x.length,0); if(!n)return; const b=newBuf(2,n,ctx.sampleRate); let o=0; R.ch[0].forEach((x,i)=>{b.getChannelData(0).set(x,o);b.getChannelData(1).set(R.ch[1][i],o);o+=x.length});
 dl(encodeWAV(b,16,DEMO?DEMO_MAX:0),'karaoke-performance.wav'); toast('Performance saved as WAV'); }
function kList(){ $('#kSongs').innerHTML=K.songs.map((s,i)=>`<button class="${i===K.cur?'on':''}" data-i="${i}">${esc(s.name)}</button>`).join('')||'<span class="hint">No songs yet</span>'; $$('#kSongs button').forEach(b=>b.onclick=()=>{kStop();K.cur=+b.dataset.i;const s=K.songs[K.cur];$('#kTxt').value=s.lyrics||'';K.lines=kParse(s.lyrics||'');kList()}); }
function initKaraoke(){ $('#kFile').onchange=async e=>{ for(const f of e.target.files){ try{ K.songs.push({name:f.name.replace(/\.[^.]+$/,''),buf:await decodeFile(f),lyrics:''}); }catch(er){toast('Cannot open '+f.name)} } e.target.value=''; if(K.cur<0&&K.songs.length)K.cur=0; kList(); };
 $('#kFromMix').onclick=async()=>{ try{ toast('Rendering your project...'); K.songs.push({name:P.name+' (mix)',buf:await renderSong({master:true}),lyrics:P.lyrics||''}); K.cur=K.songs.length-1; $('#kTxt').value=P.lyrics||''; K.lines=kParse(P.lyrics||''); kList(); }catch(e){toast(e.message)} };
 $('#kTxt').oninput=()=>{ K.lines=kParse($('#kTxt').value); if(K.songs[K.cur])K.songs[K.cur].lyrics=$('#kTxt').value; }; $('#kLyrFile').onchange=async e=>{ const f=e.target.files[0]; if(f){$('#kTxt').value=await f.text();$('#kTxt').oninput()} };
 $('#kUseLyr').onclick=()=>{ $('#kTxt').value=P.lyrics||''; $('#kTxt').oninput(); }; $('#kPlay').onclick=kPlay; $('#kMic').onclick=kMic; $('#kRec').onclick=kRec;
 $('#kNext').onclick=()=>{ K.manual=K.manual==null?0:Math.min(K.lines.length-1,K.manual+1); }; $('#kAuto').onclick=()=>{ K.manual=null; };
 $('#kMon').onchange=()=>{ if(K.mic)K.mic.mon.gain.value=$('#kMon').checked?1:0; }; }
/* ---------- tools browser (searchable) ---------- */
let LIB=null;
function buildLib(){ if(LIB)return LIB; LIB=[]; const add=(cat,name,use,tag)=>LIB.push({cat,name,use,tag});
 for(const k in FXDEF)add('Effect',FXDEF[k].n,()=>{const c=chanList().find(x=>x.id===(MSEL||SEL.t));if(!c)return toast('Select a track first');snap();c.fx.push(fxNew(k));rebuildIfPlaying();toast(FXDEF[k].n+' added to '+c.name)});
 fxPresets().forEach(p=>add('Effect preset',p.name,()=>{const c=chanList().find(x=>x.id===(MSEL||SEL.t));if(!c)return toast('Select a track first');snap();c.fx.push(fxNew(p.type,p.over));rebuildIfPlaying();toast(p.name+' added to '+c.name)}));
 for(const k in INSTDEF)add('Instrument',INSTDEF[k].n,()=>{snap();const t=addTrack('midi',k);if(t){refreshAll();toast(INSTDEF[k].n+' track added')}});
 for(const n in INST_PRESETS)add('Instrument preset',n,()=>{ const t=selTrack(); snap(); if(t&&t.kind==='midi'){t.inst=applyInstPreset(n);toast(n+' loaded on '+t.name)} else {const nt=addTrack('midi',n);if(nt)nt.name=n.slice(0,24);toast(n+' track added')} refreshAll(); });
 const writeTo=(notes,len,drums)=>{ let s=needMidiClip(); if(!s||(drums&&s.t.inst.type!=='drums')){ let t=P.tracks.find(x=>x.kind==='midi'&&(drums?x.inst.type==='drums':x.inst.type!=='drums')&&x.id===SEL.t)||addTrack('midi',drums?'drums':'Piano-ish'); if(!t)return; s={t,c:newClip(t,Math.floor(T.pos/P.sig)*P.sig,len)}; } s.c.notes=notes; s.c.len=Math.max(s.c.len,len); refreshAll(); toast('Written to '+s.c.name); };
 for(const pr in PROGS)NOTE_NAMES.forEach((kn,ki)=>['Major','Minor'].forEach(md=>add('Generator','Chords '+pr+' in '+kn+' '+md,()=>{snap();writeTo(genChords(pr,ki,md==='Minor',PROGS[pr].length),PROGS[pr].length*P.sig)})));
 GENRES.forEach(g=>{for(let v=1;v<=8;v++)add('Generator','Drums '+g+' variation '+v,()=>{snap();writeTo(genDrums(g,v,2),P.sig*2,true)})});
 NOTE_NAMES.forEach((kn,ki)=>MOODS.forEach((m,mi)=>{for(let v=1;v<=4;v++)add('Generator','Melody '+m+' in '+kn+' seed '+v,()=>{snap();writeTo(genMelody(ki,mi,v,4),P.sig*4)})}));
 ['Up','Down','Up Down','Random'].forEach(mode=>[[2,'1/8'],[4,'1/16'],[3,'Triplet'],[8,'1/32']].forEach(([r,rn])=>add('MIDI FX','Arpeggiator '+mode+' '+rn,()=>{const t=selTrack();if(!t||t.kind!=='midi')return toast('Select a synth track');snap();t.mfx=t.mfx||{};t.mfx.arp={on:true,mode,rate:r,oct:1};toast('Arpeggiator on for '+t.name)})));
 Object.keys(CHORD_SHAPES).forEach(ch=>add('MIDI FX','Chord generator '+ch,()=>{const t=selTrack();if(!t||t.kind!=='midi')return toast('Select a synth track');snap();t.mfx=t.mfx||{};t.mfx.chord={on:true,type:ch};toast('Chords on for '+t.name)}));
 ['Transpose','Humanise','Velocity scale','Scale lock','Note echo'].forEach(n=>add('MIDI FX',n,()=>showTab('inst')));
 Object.keys(SCALES).forEach(s=>NOTE_NAMES.forEach((kn,ki)=>add('Scale',kn+' '+s,()=>{showTab('tools');$('#chKey').value=ki;$('#chSc').value=s;chordView()})));
 [['Tuner (mic, A=432/440/442)','tools'],['Chord and scale helper','tools'],['BPM tap','tools'],['Key and tempo detect','tools'],['Lyric pad with rhyme finder','tools'],['Tempo map','tools'],['Markers','tools'],['Karaoke mode','karaoke'],['Vocal reducer','karaoke'],['Loudness meter and LUFS history','master'],['Spectrum analyser','master'],['Spectrogram','master'],['Phase scope and correlation meter','master'],['Reference track A/B','master'],['Mastering chain','master'],['Waveform editor','editor'],['Time-stretch (WSOLA)','editor'],['Pitch shift','editor'],['Noise reduction','editor'],['Click and pop repair','editor'],['De-reverb lite','editor'],['Reverse, normalise, fades','editor'],['Piano roll','piano'],['Step sequencer','drums'],['Freeze and bounce','arrange'],['Stems export','export'],['Video export','export'],['Project save and load','export']].forEach(([n,t])=>add('Utility',n,()=>showTab(t)));
 [60,70,80,90,100,110,120,128,140,150,160,174].forEach(b=>[2,3,4,6].forEach(s=>add('Utility','Metronome '+b+' BPM '+s+'/4',()=>{snap();P.bpm=b;P.sig=s;prefs.metro=true;$('#bMetro').classList.add('on');refreshAll();toast('Tempo '+b+', '+s+'/4, click on')}))); return LIB; }
function libView(){ const q=($('#libQ').value||'').toLowerCase().split(/\s+/).filter(Boolean),cat=$('#libCat').value,L=buildLib(); const hits=L.filter(x=>(!cat||x.cat===cat)&&q.every(w=>(x.name+' '+x.cat).toLowerCase().includes(w)));
 $('#libN').textContent=`${hits.length} of ${L.length} tools`; $('#libList').innerHTML=hits.slice(0,300).map((x,i)=>`<div><span class="tag">${x.cat}</span><span>${esc(x.name)}</span><button class="sm" data-i="${L.indexOf(x)}">Use</button></div>`).join('')+(hits.length>300?'<p class="hint">Showing the first 300. Type more to narrow it down.</p>':'');
 $$('#libList button').forEach(b=>b.onclick=()=>L[+b.dataset.i].use()); }
/* ---------- export and project ---------- */
async function exportMix(){ const fmt=$('#exFmt').value; toast('Rendering...',60000); try{ const b=await renderSong({master:$('#exMaster').checked}); await saveAudio(b,fmt,P.name||'mix'); }catch(e){toast(e.message)} }
async function saveAudio(b,fmt,name){ let blob,ext; if(fmt==='mp3'){ blob=await encodeMP3(b,DEMO?DEMO_MAX:0,192); ext='mp3'; } else { blob=encodeWAV(b,+fmt,DEMO?DEMO_MAX:0); ext='wav'; } dl(blob,name.replace(/[^\w -]/g,'')+'.'+ext); toast('Saved '+name+'.'+ext+(DEMO?' (demo: 30 seconds max)':'')); return blob; }
async function exportStems(){ const fmt=$('#exFmt').value,ts=realTracks().filter(t=>t.clips.length); if(!ts.length)return toast('Nothing to export'); for(const t of ts){ toast('Rendering stem '+t.name,60000); const b=await renderSong({only:t.id}); await saveAudio(b,fmt,(P.name||'song')+' - '+t.name); await new Promise(r=>setTimeout(r,400)); } toast(ts.length+' stems saved'); }
async function exportVideo(){ if(!window.MediaRecorder)return toast('Video recording is not supported in this browser'); toast('Rendering, then recording the video in real time...',8000); const b=await renderSong({master:$('#exMaster').checked}); const c=AC(),dest=c.createMediaStreamDestination(),src=c.createBufferSource(); src.buffer=b; const an=c.createAnalyser(); an.fftSize=256; src.connect(an); an.connect(dest);
 const cv=document.createElement('canvas'); cv.width=1280; cv.height=720; const g=cv.getContext('2d'),logo=$('.logo'),fd=new Uint8Array(128); const st=cv.captureStream(30); st.addTrack(dest.stream.getAudioTracks()[0]);
 const mime=['video/mp4;codecs=avc1,mp4a','video/webm;codecs=vp9,opus','video/webm'].find(m=>MediaRecorder.isTypeSupported(m))||''; const rec=new MediaRecorder(st,mime?{mimeType:mime}:{}),parts=[]; rec.ondataavailable=e=>parts.push(e.data);
 let on=true; const draw=()=>{ if(!on)return; an.getByteFrequencyData(fd); g.fillStyle='#2e1422'; g.fillRect(0,0,1280,720); g.drawImage(logo,40,40,120,120); g.fillStyle='#ffd6e8'; g.font='bold 54px sans-serif'; g.fillText(P.name||'Coffeebreak',190,120); for(let i=0;i<100;i++){const v=fd[i]/255;g.fillStyle='#e75b9a';g.fillRect(40+i*12,680-v*420,9,v*420)} requestAnimationFrame(draw); };
 rec.start(); src.start(); draw(); await new Promise(r=>src.onended=r); on=false; rec.stop(); await new Promise(r=>rec.onstop=r); const ext=mime.includes('mp4')?'mp4':'webm'; dl(new Blob(parts,{type:mime||'video/webm'}),(P.name||'song')+'.'+ext); toast('Video saved as '+ext.toUpperCase()); }
function usedBufIds(){ const s=new Set(); P.tracks.forEach(t=>{ t.clips.forEach(c=>(c.takes||[]).forEach(i=>s.add(i))); if(t.inst&&t.inst.buf)s.add(t.inst.buf); }); return[...s].filter(i=>BUFS[i]); }
function packProject(){ const ids=usedBufIds(),meta={},parts=[]; let off=0; ids.forEach(id=>{ const b=BUFS[id]; meta[id]={sr:b.sampleRate,ch:b.numberOfChannels,len:b.length,off}; for(let c=0;c<b.numberOfChannels;c++){parts.push(b.getChannelData(c).slice());off+=b.length*4} });
 const js=new TextEncoder().encode(JSON.stringify({app:'Coffeebreak Studio Espresso',v:1,project:P,bufs:meta})),hd=new Uint32Array([js.length]); return new Blob([new TextEncoder().encode('CBX1'),hd,js,...parts],{type:'application/octet-stream'}); }
async function unpackProject(ab){ const u8=new Uint8Array(ab); if(new TextDecoder().decode(u8.slice(0,4))!=='CBX1')throw new Error('Not a Studio Espresso project file'); const n=new Uint32Array(ab.slice(4,8))[0],j=JSON.parse(new TextDecoder().decode(u8.slice(8,8+n))),base=8+n;
 for(const id in j.bufs){ const m=j.bufs[id],b=newBuf(m.ch,m.len,m.sr); for(let c=0;c<m.ch;c++)b.copyToChannel(new Float32Array(ab.slice(base+m.off+c*m.len*4,base+m.off+(c+1)*m.len*4)),c); BUFS[id]=b; } stop(); P=j.project; HIST.length=0; refreshAll(); }
function idb(){ return new Promise((res,rej)=>{ let r; try{r=indexedDB.open('cb-studio-x',1)}catch(e){return rej(e)} r.onupgradeneeded=()=>r.result.createObjectStore('projects'); r.onsuccess=()=>res(r.result); r.onerror=()=>rej(r.error); }); }
async function idbDo(mode,fn){ const db=await idb(); return new Promise((res,rej)=>{ const tx=db.transaction('projects',mode),r=fn(tx.objectStore('projects')); tx.oncomplete=()=>res(r&&r.result); tx.onerror=()=>rej(tx.error); }); }
async function saveLocal(){ try{ const ab=await packProject().arrayBuffer(); await idbDo('readwrite',s=>s.put(ab,P.name||'My song')); toast('Saved "'+(P.name||'My song')+'" in this browser'); projList(); }catch(e){ toast('Browser storage is blocked here. Use Export project file instead.'); } }
async function projList(){ const el=$('#projList'); if(!el)return; try{ const ks=await idbDo('readonly',s=>s.getAllKeys()); el.innerHTML=(ks||[]).map(k=>`<button data-k="${esc(k)}">Open ${esc(k)}</button><button class="sm" data-d="${esc(k)}">Delete</button>`).join('')||'<span class="hint">No saved projects yet</span>';
 $$('#projList [data-k]').forEach(b=>b.onclick=async()=>{ const ab=await idbDo('readonly',s=>s.get(b.dataset.k)); await unpackProject(ab); toast('Opened '+b.dataset.k); }); $$('#projList [data-d]').forEach(b=>b.onclick=async()=>{ if(!confirm('Delete saved project '+b.dataset.d+'?'))return; await idbDo('readwrite',s=>s.delete(b.dataset.d)); projList(); }); }catch(e){ el.innerHTML='<span class="hint">Browser storage is not available here. Use project files.</span>'; } }
function initExport(){ if(!hasMP3())$('#exFmt option[value=mp3]').remove(); $('#exMix').onclick=exportMix; $('#exStems').onclick=exportStems; $('#exVid').onclick=exportVideo; $('#pName').value=P.name; $('#pName').onchange=()=>{P.name=$('#pName').value};
 $('#pSave').onclick=saveLocal; $('#pExp').onclick=()=>{ dl(packProject(),(P.name||'song')+'.cbe'); toast('Project file saved'); }; $('#pImp').onchange=async e=>{ const f=e.target.files[0]; if(!f)return; try{ await unpackProject(await f.arrayBuffer()); toast('Project opened'); }catch(er){ toast(er.message); } e.target.value=''; };
 $('#pNew').onclick=()=>{ if(!confirm('Start a new empty project? Unsaved changes will be lost.'))return; stop(); snap(); P=newProject(); refreshAll(); }; $('#pDemo').onclick=()=>{ stop(); snap(); demoSong(); refreshAll(); toast('Demo song loaded'); }; }
