/* ---------- demo song ---------- */
function demoSong(){ P=newProject(); P.name='Coffeebreak demo'; P.bpm=110; const S=P.sig;
 const keys=addTrack('midi','Electric piano','Keys'); keys.clips=[]; const kc=newClip(keys,0,S*4,{name:'Chords'}); kc.notes=genChords('I-V-vi-IV',0,false,4); keys.sendA=0.25; keys.fx.push(fxNew('chorus',{mix:0.3}));
 const dr=addTrack('midi','drums','Drums'); const dc=newClip(dr,0,S*4,{name:'Beat'}); dc.notes=genDrums('Pop',1,4); dr.fx.push(fxNew('comp',{threshold:-14,ratio:3})); dr.sendA=0.1;
 if(!DEMO){ const bass=addTrack('midi','Round bass','Bass'); const bc=newClip(bass,0,S*4,{name:'Bass'}); bc.notes=[0,7,9,5].flatMap((d,i)=>[{p:36+d,s:i*S,l:1.5,v:0.85},{p:36+d,s:i*S+2,l:1,v:0.7}]); bass.fx.push(fxNew('duck',{amount:0.4})); bass.fx[0].src=dr.id;
  const ld=addTrack('midi','Pedal-steel lead','Lead'); const lc=newClip(ld,S*4,S*4,{name:'Melody'}); lc.notes=genMelody(0,0,3,4); ld.sendB=0.3; ld.vol=0.6; ld.auto.vol=[[S*4,0.2],[S*5,0.6],[S*8,0.6]];
  const au=addTrack('audio',null,'Vocal pad'); const sr=48000,len=Math.round(sr*b2s(S*4)),b=newBuf(2,len,sr); for(let c=0;c<2;c++){const d=b.getChannelData(c);for(let i=0;i<len;i++){const t=i/sr;d[i]=0.18*Math.sin(2*Math.PI*(220+3*Math.sin(t*5))*t)*Math.min(1,t*4)*Math.min(1,(len-i)/sr*4)+0.04*Math.sin(2*Math.PI*330*t+c)}}
  audioClip(au,b,S*4,'Pad'); au.fx.push(fxNew('eq',{g4:2})); au.sendA=0.3;
  const kc2=JSON.parse(JSON.stringify(kc)); kc2.id=nid('c'); kc2.start=S*4; keys.clips.push(kc2); const dc2=JSON.parse(JSON.stringify(dc)); dc2.id=nid('c'); dc2.start=S*4; dc2.notes=genDrums('Pop',3,4); dr.clips.push(dc2); const bc2=JSON.parse(JSON.stringify(bc)); bc2.id=nid('c'); bc2.start=S*4; bass.clips.push(bc2);
  P.markers=[{b:0,name:'Intro'},{b:S*4,name:'Verse'}]; }
 P.loop={on:false,s:0,e:S*4}; SEL.t=P.tracks[0].id; SEL.c=null; P.lyrics='Sun is up on the Coffeebreak farm\nPink boots on and a basket on my arm\nKicking marshmallows up the mud\nPink and white flying where the puddles flood'; }
