const VIEWS={arrange:()=>{renderHeads();drawTL();renderInspector()},piano:prView,drums:drView,inst:instView,mixer:mixView,editor:edView,master:masterView,library:libView,export:projList,tools:tmView};
function initKeys(){ const held={}; window.addEventListener('keydown',e=>{ const tag=e.target.tagName; if(/INPUT|SELECT|TEXTAREA/.test(tag)&&e.target.type!=='range'&&e.target.type!=='checkbox')return; const k=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;
  if(prefs.keys&&!mod&&CKEYS.includes(k)&&CUR==='piano'){ if(!held[k]){held[k]=1;midiOn(KOCT*12+12+CKEYS.indexOf(k),0.8)} e.preventDefault(); return; }
  if(k===' '){e.preventDefault();play()} else if(k==='home'||k==='enter'){e.preventDefault();goStart()} else if(mod&&k==='z'){e.preventDefault();e.shiftKey?redo():undo()} else if(mod&&k==='y'){e.preventDefault();redo()} else if(mod&&k==='s'){e.preventDefault();saveLocal()}
  else if(mod&&k==='c'){const c=selClip();if(c){CLIPBOARD=JSON.parse(JSON.stringify(c));toast('Clip copied')}} else if(mod&&k==='v'){const t=selTrack();if(CLIPBOARD&&t&&t.kind!=='bus'&&(t.kind==='audio')===(CLIPBOARD.takes.length>0)){snap();const n=JSON.parse(JSON.stringify(CLIPBOARD));n.id=nid('c');n.start=T.pos;t.clips.push(n);SEL.c=n.id;refreshAll()}}
  else if(mod&&k==='d'){e.preventDefault();const t=selTrack(),c=selClip();if(c)dupClip(t,c)} else if(mod)return; else if(k==='r')record(); else if(k==='l')$('#bLoop').click(); else if(k==='m')$('#bMetro').click(); else if(k==='s'){const t=selTrack(),c=selClip();if(c)splitClip(t,c,T.pos)}
  else if(k==='delete'||k==='backspace'){if(CUR==='arrange'){e.preventDefault();delClip()}} else if(k==='+'||k==='='){Z=Math.min(160,Z*1.25);drawTL()} else if(k==='-'){Z=Math.max(6,Z/1.25);drawTL()} else if(/^[1-9]$/.test(k)){showTab(TABS[+k-1][0])} });
 window.addEventListener('keyup',e=>{ const k=e.key.toLowerCase(); if(held[k]){delete held[k];midiOff(KOCT*12+12+CKEYS.indexOf(k))} }); }
function init(){ applyTheme(); buildSections(); if(DEMO){$('#demoBanner').classList.remove('hidden');$('#sub').textContent='Free demo';}
 $('#bPlay').onclick=()=>play(); $('#bStop').onclick=goStart; $('#bRec').onclick=record; $('#bUndo').onclick=undo; $('#bRedo').onclick=redo; $('#bSave').onclick=saveLocal;
 $('#bLoop').onclick=()=>{ snap(); P.loop.on=!P.loop.on; if(P.loop.on&&P.loop.e<=P.loop.s){P.loop.s=Math.floor(T.pos/P.sig)*P.sig;P.loop.e=P.loop.s+P.sig*4} $('#bLoop').classList.toggle('on',P.loop.on); drawTL(); };
 $('#bMetro').classList.toggle('on',!!prefs.metro); $('#bMetro').onclick=()=>{prefs.metro=!prefs.metro;LS.set('cbx-prefs',prefs);$('#bMetro').classList.toggle('on',prefs.metro)};
 $('#bCount').classList.toggle('on',!!prefs.count); $('#bCount').onclick=()=>{prefs.count=!prefs.count;LS.set('cbx-prefs',prefs);$('#bCount').classList.toggle('on',prefs.count)};
 $('#bPunch').onclick=()=>{ snap(); P.punch=!P.punch; $('#bPunch').classList.toggle('on',P.punch); if(P.punch&&!P.loop.on)toast('Punch records only inside the loop region. Turn Loop on and set the region.'); };
 $('#iBpm').onchange=()=>{ snap(); P.bpm=Math.max(30,Math.min(300,+$('#iBpm').value||120)); rebuildIfPlaying(); refreshAll(); }; $('#iSig').onchange=()=>{ snap(); P.sig=+$('#iSig').value; refreshAll(); };
 $('#aAud').onclick=()=>{snap();if(addTrack('audio'))refreshAll()}; $('#aSyn').onclick=()=>{snap();if(addTrack('midi','sub'))refreshAll()}; $('#aDrm').onclick=()=>{snap();if(addTrack('midi','drums'))refreshAll()}; $('#aBus').onclick=()=>{snap();addTrack('bus');refreshAll();toast('Bus added. Route tracks to it with their output menu.')};
 $('#aImp').onclick=()=>$('#impFile').click(); $('#aMk').onclick=()=>{const n=prompt('Marker name','Chorus');if(n){snap();P.markers.push({b:T.pos,name:n});drawTL()}}; $('#aZi').onclick=()=>{Z=Math.min(160,Z*1.25);drawTL()}; $('#aZo').onclick=()=>{Z=Math.max(6,Z/1.25);drawTL()};
 $$('#t-arrange [data-m]').forEach(b=>b.onclick=()=>{ARR_MODE=b.dataset.m;$$('#t-arrange [data-m]').forEach(x=>x.classList.toggle('on',x===b))});
 $('#kOd').onclick=()=>{KOCT=Math.max(1,KOCT-1);renderKeys()}; $('#kOu').onclick=()=>{KOCT=Math.min(7,KOCT+1);renderKeys()};
 initArrange(); initPiano(); initDrums(); initInst(); initEditor(); initMaster(); initTools(); initKaraoke(); initExport(); initSettings(); initKeys();
 $('#libQ').oninput=libView; $('#libCat').onchange=libView; $('#prCk').classList.toggle('on',!!prefs.keys); $('#prCk').textContent='Computer keys: '+(prefs.keys?'on':'off');
 demoSong(); showTab('arrange'); refreshAll(); requestAnimationFrame(frame); window.addEventListener('resize',()=>drawTL());
 document.addEventListener('pointerdown',()=>{ if(ctx&&ctx.state==='suspended')ctx.resume(); },{passive:true}); }
init();
